import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, timestampColumns } from "./_shared";

/** Users are global, not tenant-scoped: one account can join many orgs. */
export const users = sqliteTable(
  "users",
  {
    id: idColumn(),
    email: text("email").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    avatarUrl: text("avatar_url"),
    timezone: text("timezone").notNull().default("UTC"),
    emailVerifiedAt: text("email_verified_at"),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("users_email_idx").on(table.email)],
);

export const sessions = sqliteTable(
  "sessions",
  {
    id: idColumn(),
    userId: text("user_id").notNull(),
    activeOrgId: text("active_org_id"),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("sessions_token_idx").on(table.tokenHash)],
);

export const passwordResetTokens = sqliteTable("password_reset_tokens", {
  id: idColumn(),
  userId: text("user_id").notNull(),
  tokenHash: text("token_hash").notNull(),
  expiresAt: text("expires_at").notNull(),
  usedAt: text("used_at"),
  ...timestampColumns,
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
export type SessionRow = typeof sessions.$inferSelect;
/**
 * Session cookie access. In Next 16 `cookies()` is async — every function
 * here is async for that reason, and nothing outside this module touches the
 * cookie jar, so the cookie's name, flags and lifetime are stated once.
 */
import { cookies } from "next/headers";
import { SESSION_COOKIE_NAME } from "@/schemas/session";
import { resolveSession } from "@/server/services/session-service";
import type { IsoTimestamp } from "@/types/common";
import type { SessionPrincipal } from "@/types/member";
import { parseIso } from "./date";

export async function getSessionToken(): Promise<string | null> {
  const jar = await cookies();
  return jar.get(SESSION_COOKIE_NAME)?.value ?? null;
}

/**
 * The signed-in principal, or `null` when there is no cookie, the token is
 * unknown, or the session has expired. Callers that need a hard failure use
 * `getActor()` in `@/lib/actor` instead.
 */
export async function getSessionPrincipal(): Promise<SessionPrincipal | null> {
  const token = await getSessionToken();
  if (token === null) return null;

  const principal = await resolveSession(token);
  if (principal === null) return null;

  return parseIso(principal.expiresAt).getTime() > Date.now() ? principal : null;
}

export async function setSessionCookie(
  token: string,
  expiresAt: IsoTimestamp,
): Promise<void> {
  const jar = await cookies();
  jar.set(SESSION_COOKIE_NAME, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    expires: parseIso(expiresAt),
  });
}

export async function clearSessionCookie(): Promise<void> {
  const jar = await cookies();
  jar.delete(SESSION_COOKIE_NAME);
}
/**
 * Global user rows. The only repository that is NOT tenant scoped — users exist across organizations.
 */
import { eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUser } from "./_mappers";
import type { UpdateProfileInput } from "@/schemas/member";
import type { UserId } from "@/types/common";
import type { User } from "@/types/member";

export async function findUserById(userId: UserId): Promise<User | null> {
  const rows = getDb().select().from(users).where(eq(users.id, userId)).all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

export async function findUserByEmail(email: string): Promise<User | null> {
  const rows = getDb()
    .select()
    .from(users)
    .where(eq(users.email, email.toLowerCase()))
    .all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

export async function insertUser(input: {
  email: string;
  name: string;
  passwordHash: string;
}): Promise<User> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(users)
    .values({
      id: newId(),
      email: input.email.toLowerCase(),
      name: input.name,
      passwordHash: input.passwordHash,
      avatarUrl: null,
      timezone: "UTC",
      emailVerifiedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toUser(row);
}

export async function updateUser(
  userId: UserId,
  patch: UpdateProfileInput,
): Promise<User> {
  const row = getDb()
    .update(users)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.avatarUrl === undefined ? {} : { avatarUrl: patch.avatarUrl }),
      ...(patch.timezone === undefined ? {} : { timezone: patch.timezone }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(users.id, userId))
    .returning()
    .get();

  if (!row) throw new Error(`User ${userId} not found`);
  return toUser(row);
}

/**
 * The password hash never travels on the `User` domain type — nothing outside
 * `AuthService` may see it — so login reads it through this narrow accessor.
 *
 * Not in the manifest: added because `User` deliberately omits the column and
 * credential login has no other way to reach it.
 */
export async function findPasswordHash(
  userId: UserId,
): Promise<string | null> {
  const row = getDb()
    .select({ passwordHash: users.passwordHash })
    .from(users)
    .where(eq(users.id, userId))
    .get();
  return row?.passwordHash ?? null;
}

/** Counterpart of `findPasswordHash`, used by the password-reset flow. */
export async function updatePasswordHash(
  userId: UserId,
  passwordHash: string,
): Promise<void> {
  getDb()
    .update(users)
    .set({ passwordHash, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(users.id, userId))
    .run();
}

/** Batch fetch used by every list view that decorates rows with their author. */
export async function findUsersByIds(
  userIds: readonly UserId[],
): Promise<readonly User[]> {
  if (userIds.length === 0) return [];
  const rows = getDb()
    .select()
    .from(users)
    .where(inArray(users.id, [...userIds]))
    .all();
  return rows.map(toUser);
}
