/**
 * Sign-in, sign-out and password reset: session lifetimes, per-session
 * sign-out, single-use reset links and per-account throttling.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

const sentTokens: string[] = [];
vi.mock("@/server/services/email-service", () => ({
  renderEmail: async (_template: string, props: Record<string, unknown>) => {
    if (typeof props.token === "string") sentTokens.push(props.token);
    return { subject: "s", html: "<p>h</p>", text: "t" };
  },
  sendEmail: async () => undefined,
}));

import { resetRateLimits } from "@/lib/rate-limit";
import * as authService from "@/server/services/auth-service";
import * as sessionService from "@/server/services/session-service";
import * as userRepo from "@/server/repositories/user-repository";
import { hashPassword } from "@/lib/hash";
import { useTemporaryDatabase } from "../server/_support/fixtures";
import type { User } from "@/types/member";

const HOUR = 60 * 60 * 1000;
const DAY = 24 * HOUR;
const PASSWORD = "Correct-Horse-1";

let cleanup: () => void;
let counter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
  sentTokens.length = 0;
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
});

afterEach(() => {
  vi.useRealTimers();
});

async function makeUser(): Promise<User> {
  counter += 1;
  return userRepo.insertUser({
    email: `person${counter}@auth.test`,
    name: `Person ${counter}`,
    passwordHash: await hashPassword(PASSWORD),
  });
}

function credentials(user: User, rememberMe = false, password = PASSWORD) {
  return { email: user.email, password, rememberMe };
}

describe("sessions", () => {
  it("signing out ends only that session", async () => {
    const ada = await makeUser();
    const bob = await makeUser();
    const laptop = await authService.login(credentials(ada));
    const phone = await authService.login(credentials(ada));
    const other = await authService.login(credentials(bob));

    await sessionService.destroySession(laptop.token);

    expect(await sessionService.resolveSession(laptop.token)).toBeNull();
    expect(await sessionService.resolveSession(phone.token)).not.toBeNull();
    expect(await sessionService.resolveSession(other.token)).not.toBeNull();
  });

  it("signing out an unknown or ended session is harmless", async () => {
    const ada = await makeUser();
    const { token } = await authService.login(credentials(ada));

    await sessionService.destroySession("no-such-token");
    await sessionService.destroySession(token);
    await sessionService.destroySession(token);

    const again = await authService.login(credentials(ada));
    expect(await sessionService.resolveSession(again.token)).not.toBeNull();
  });

  it("lasts a day without remember me and a month with it", async () => {
    const ada = await makeUser();
    const short = await authService.login(credentials(ada));
    const long = await authService.login(credentials(ada, true));

    expect(Date.parse(short.expiresAt)).toBe(Date.now() + DAY);
    expect(Date.parse(long.expiresAt)).toBe(Date.now() + 30 * DAY);

    vi.setSystemTime(Date.now() + DAY + 1000);
    expect(await sessionService.resolveSession(short.token)).toBeNull();
    expect(await sessionService.resolveSession(long.token)).not.toBeNull();

    vi.setSystemTime(Date.now() + 30 * DAY);
    expect(await sessionService.resolveSession(long.token)).toBeNull();
  });
});

describe("password reset", () => {
  it("accepts a link for 60 minutes, once", async () => {
    const ada = await makeUser();
    await authService.requestPasswordReset({ email: ada.email });
    const [token] = sentTokens;
    const next = "Another-Pass-99";

    vi.setSystemTime(Date.now() + 59 * 60_000);
    await authService.confirmPasswordReset({
      token: token!,
      password: next,
      confirmPassword: next,
    });

    await expect(
      authService.confirmPasswordReset({
        token: token!,
        password: "Third-Pass-123",
        confirmPassword: "Third-Pass-123",
      }),
    ).rejects.toThrow(/no longer valid/);

    await expect(authService.login(credentials(ada))).rejects.toThrow();
    await expect(
      authService.login(credentials(ada, false, next)),
    ).resolves.toBeDefined();
  });

  it("refuses a link after 60 minutes", async () => {
    const ada = await makeUser();
    await authService.requestPasswordReset({ email: ada.email });

    vi.setSystemTime(Date.now() + HOUR + 1000);
    await expect(
      authService.confirmPasswordReset({
        token: sentTokens[0]!,
        password: "Another-Pass-99",
        confirmPassword: "Another-Pass-99",
      }),
    ).rejects.toThrow(/no longer valid/);
  });

  it("a new link retires earlier ones of the same account only", async () => {
    const ada = await makeUser();
    const bob = await makeUser();
    await authService.requestPasswordReset({ email: ada.email });
    await authService.requestPasswordReset({ email: bob.email });
    await authService.requestPasswordReset({ email: ada.email.toUpperCase() });
    const [adaFirst, bobLink, adaSecond] = sentTokens;
    const next = "Another-Pass-99";

    await expect(
      authService.confirmPasswordReset({
        token: adaFirst!,
        password: next,
        confirmPassword: next,
      }),
    ).rejects.toThrow(/no longer valid/);
    await authService.confirmPasswordReset({
      token: bobLink!,
      password: next,
      confirmPassword: next,
    });
    await authService.confirmPasswordReset({
      token: adaSecond!,
      password: next,
      confirmPassword: next,
    });
  });

  it("ends every session of that account and nobody else's", async () => {
    const ada = await makeUser();
    const bob = await makeUser();
    const laptop = await authService.login(credentials(ada));
    const phone = await authService.login(credentials(ada, true));
    const other = await authService.login(credentials(bob));

    await authService.requestPasswordReset({ email: ada.email });
    await authService.confirmPasswordReset({
      token: sentTokens[0]!,
      password: "Another-Pass-99",
      confirmPassword: "Another-Pass-99",
    });

    expect(await sessionService.resolveSession(laptop.token)).toBeNull();
    expect(await sessionService.resolveSession(phone.token)).toBeNull();
    expect(await sessionService.resolveSession(other.token)).not.toBeNull();
  });

  it("completes silently for an unknown address", async () => {
    await expect(
      authService.requestPasswordReset({ email: "nobody@auth.test" }),
    ).resolves.toBeUndefined();
    expect(sentTokens).toHaveLength(0);
  });
});

describe("throttling", () => {
  it("limits sign-in attempts per account, ignoring letter case", async () => {
    const ada = await makeUser();
    const bob = await makeUser();

    let refused = false;
    for (let i = 0; i < 100 && !refused; i += 1) {
      const email = i % 2 === 0 ? ada.email : ada.email.toUpperCase();
      try {
        await authService.login({ email, password: "wrong", rememberMe: false });
      } catch (error) {
        refused = /Too many/.test((error as Error).message);
      }
    }
    expect(refused).toBe(true);

    await expect(authService.login(credentials(ada))).rejects.toThrow(/Too many/);
    await expect(authService.login(credentials(bob))).resolves.toBeDefined();

    vi.setSystemTime(Date.now() + HOUR);
    await expect(authService.login(credentials(ada))).resolves.toBeDefined();
  });

  it("a throttled account can still reset its password", async () => {
    const ada = await makeUser();
    for (let i = 0; i < 100; i += 1) {
      await authService
        .login({ email: ada.email, password: "wrong", rememberMe: false })
        .catch(() => undefined);
    }
    await expect(authService.login(credentials(ada))).rejects.toThrow(/Too many/);

    await authService.requestPasswordReset({ email: ada.email });
    expect(sentTokens).toHaveLength(1);
    await authService.confirmPasswordReset({
      token: sentTokens[0]!,
      password: "Another-Pass-99",
      confirmPassword: "Another-Pass-99",
    });
  });

  it("limits reset requests per address, not globally", async () => {
    const ada = await makeUser();
    const bob = await makeUser();

    for (let i = 0; i < 20; i += 1) {
      await authService.requestPasswordReset({ email: ada.email });
    }
    const sentForAda = sentTokens.length;
    expect(sentForAda).toBeLessThan(20);

    await authService.requestPasswordReset({ email: bob.email });
    expect(sentTokens).toHaveLength(sentForAda + 1);

    await expect(authService.login(credentials(ada))).resolves.toBeDefined();
  });
});

